nnouncement-false","source":"knowledge-current-announcement","target":"knowledge-30","sourceHandle":"false"},{"id":"knowledge-edge-knowledge-current-announcement-true","source":"knowledge-current-announcement","target":"knowledge-8","sourceHandle":"true"},{"id":"knowledge-edge-knowledge-12-success","source":"knowledge-12","target":"knowledge-latest-publication","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-latest-publication-success","source":"knowledge-latest-publication","target":"knowledge-filter-publication","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-filter-publication-success","source":"knowledge-filter-publication","target":"knowledge-current-publication","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-latest-publication-error","source":"knowledge-latest-publication","target":"knowledge-32","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-filter-publication-error","source":"knowledge-filter-publication","target":"knowledge-32","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-current-publication-false","source":"knowledge-current-publication","target":"knowledge-33","sourceHandle":"false"},{"id":"knowledge-edge-knowledge-current-publication-true","source":"knowledge-current-publication","target":"knowledge-13","sourceHandle":"true"},{"id":"knowledge-edge-knowledge-12-error","source":"knowledge-12","target":"knowledge-latest-failure","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-latest-failure-success","source":"knowledge-latest-failure","target":"knowledge-filter-failure","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-filter-failure-success","source":"knowledge-filter-failure","target":"knowledge-current-failure","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-latest-failure-error","source":"knowledge-latest-failure","target":"knowledge-32","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-filter-failure-error","source":"knowledge-filter-failure","target":"knowledge-32","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-current-failure-false","source":"knowledge-current-failure","target":"knowledge-33","sourceHandle":"false"},{"id":"knowledge-edge-knowledge-current-failure-true","source":"knowledge-current-failure","target":"knowledge-14","sourceHandle":"true"},{"id":"knowledge-edge-knowledge-5-error","source":"knowledge-5","target":"knowledge-31","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-6-error","source":"knowledge-6","target":"knowledge-31","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-7-false","source":"knowledge-7","target":"knowledge-30","sourceHandle":"false"},{"id":"knowledge-edge-knowledge-8-error","source":"knowledge-8","target":"knowledge-34","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-9-false","source":"knowledge-9","target":"knowledge-29","sourceHandle":"false"},{"id":"knowledge-edge-knowledge-11-error","source":"knowledge-11","target":"knowledge-34","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-13-success","source":"knowledge-13","target":"knowledge-33","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-13-error","source":"knowledge-13","target":"knowledge-32","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-14-success","source":"knowledge-14","target":"knowledge-33","sourceHandle":"success"},{"id":"knowledge-edge-knowledge-14-error","source":"knowledge-14","target":"knowledge-32","sourceHandle":"error"},{"id":"knowledge-edge-knowledge-source-message-error","source":"knowledge-source-message","target":"knowledge-31","sourceHandle":"error"}]}
$patch$::jsonb;
    target record;
    graph jsonb;
    node jsonb;
    delta jsonb;
    config jsonb;
    nodes jsonb;
    edges jsonb;
begin
    for target in select * from automation_trigger
        where workflow_definition is not null
          and workflow_definition::jsonb->>'entryNodeId' = 'knowledge-1'
          and not exists (select 1 from jsonb_array_elements(workflow_definition::jsonb->'nodes') n
                          where n->>'id' = 'knowledge-source-message')
        for update
    loop
        insert into automation_workflow_backup(trigger_id,migration_version,definition)
            values(target.id,67,to_jsonb(target)) on conflict do nothing;
        graph := target.workflow_definition::jsonb;
        select coalesce(jsonb_agg(e), '[]'::jsonb) into edges
            from jsonb_array_elements(graph->'edges') e
            where not (patch->'replaceEdgeSources' ? (e->>'source'));
        edges := edges || (patch->'edges');
        nodes := '[]'::jsonb;
        for node in select * from jsonb_array_elements(graph->'nodes')
        loop
            if patch->'removeNodeIds' ? (node->>'id') and not exists
                (select 1 from jsonb_array_elements(edges) e where e->>'target' = node->>'id' or e->>'source' = node->>'id')
            then continue; end if;
            delta := patch->'updates'->(node->>'id');
            if delta is not null then
                config := coalesce(node->'config','{}'::jsonb) || coalesce(delta->'config','{}'::jsonb);
                if delta#>'{config,arguments}' is not null then
                    config := jsonb_set(config,'{arguments}',coalesce(node#>'{config,arguments}','{}'::jsonb) || (delta#>'{config,arguments}'));
                end if;
                node := node || (delta - 'config') || jsonb_build_object('config',config);
            end if;
            nodes := nodes || jsonb_build_array(node);
        end loop;
        graph := graph || jsonb_build_object('nodes',nodes || (patch->'addNodes'),'edges',edges);
        update automation_trigger set workflow_definition=graph::text where id=target.id;
    end loop;
end
$migration$;
